/* Remove patients who died before january 1 2000 */

select distinct a.ScrSSN,  b.MPI_DOD
into #tempdeath
from Dflt.HeartFailureinitial as a with (NOLOCK) inner join
Src.SDAF_DAFMaster as b with (NOLOCK) on a.scrssn= b.MPI_scrssn
where b.MPI_DOD < '2000-01-01 00:00:00'

