select distinct scrssn from #temphficd --984,515

select distinct scrssn, icd9code, recenthfdatetime 
into #temphfcode
from #temphficd

select scrssn, count( ICD9code) as TotalHFICDCodes

into #tempcounticdcode

from #temphfcode group by (scrssn)

select * from #tempcounticdcode

select * from #temphfcode where scrssn = '336673267'

select distinct scrssn from #tempcounticdcode --984,515

select distinct scrssn from #tempcounticdcode where TotalHFICDCodes >=2 -- 820,646

select distinct scrssn from #tempcounticdcode where TotalHFICDCodes < 2 --163,103

select a.scrssn, b.patientsid, b.sta3n, b.DischargeDateTime, b.FirstHF_DischargeDatetime
into Dflt.Heartfailure_2HFcodes
from #tempcounticdcode as a with (NOLOCK) inner join 
Dflt.heartfailure as b with (NOLOCK) on a.ScrSSN= b.scrssn where TotalHFICDCodes >=2

select distinct scrssn from Dflt.Heartfailure_2HFcodes --820,646

alter table Dflt.Heartfailure_2HFcodes rebuild with (data_compression=page)

/* Find the Closest LVEF date and value */

select distinct a.*, b.Low_Value, b.ValueDateTime, b.High_Value, ABS(datediff(day,a.FirstHF_DischargeDatetime, b.ValueDateTime)) as closestdate

into #tempclosestef

from Dflt.Heartfailure_2HFcodes as a with (NOLOCK) inner join 
Src.VINCI_TIU_NLP_LVEF as b with (NOLOCK) on a.PatientSID= b.PatientSID 
--where b.Low_Value <= 49 and  b.ValueDateTime between dateadd(year, -1, a.FirstHF_DischargeDatetime) and dateadd(month, 6, a.FirstHF_DischargeDatetime)

select distinct scrssn from #tempclosestef --766,502
select top 1000* from #tempclosestef
select * from #tempclosestef

select * from #tempclosestef where scrssn = '292016796'

select scrssn , min(closestdate) as closestdate

into #tempclosestlvef

from #tempclosestef 
group by scrssn

select distinct scrssn from #tempclosestlvef --766,502

select distinct a.scrssn, a.patientsid, a.sta3n, a.DischargeDateTime, a.FirstHF_DischargeDatetime, 
a.Low_Value,a.high_value,cast(a.ValueDateTime as date) as valuedatetime ,
b.closestdate

into Dflt.Heartfailure_ClosestEF

from #tempclosestef as a with (NOLOCK) inner join 
#tempclosestlvef as b with (NOLOCK) on a.scrssn= b.scrssn 
where a.closestdate = b.closestdate

select distinct scrssn from Dflt.Heartfailure_ClosestEF --766,488
select top 1000* from Dflt.Heartfailure_ClosestEF
select * from Dflt.Heartfailure_ClosestEF where scrssn = '772565581'

alter table Dflt.Heartfailure_ClosestEF rebuild with (data_compression=page)

/* LVEF < 50% */

select distinct *

into #temphfref

from  Dflt.Heartfailure_ClosestEF
where Low_Value < 50 

select distinct scrssn from #temphfref --458,821

select distinct *

into #temphfpef

from  Dflt.Heartfailure_ClosestEF
where Low_Value >= 50 

select distinct scrssn from #temphfpef --376,857

select distinct a.*, b.Low_Value as hfpef_value
into #tempoverlap
from #temphfref as a with (NOLOCK) inner join 
#temphfpef as b with (NOLOCK) on a.scrssn= b.scrssn 

select distinct scrssn from #tempoverlap --69,190

Select b.scrssn, b.patientsid, b.sta3n, b.FirstHF_DischargeDatetime, b.Low_Value,b.valuedatetime,b.closestdate

into #temphfpefhfref

from #tempoverlap as a with (NOLOCK) inner join
#tempclosestef as b with (NOLOCK) on a.scrssn= b.scrssn 

select distinct scrssn from #temphfpefhfref --69,190
select top 100* from #tempclosestef

Select *

into #temphfreffinal

from #temphfref as a where a.FirstHF_DischargeDatetime >= '2000-01-01 00:00:00'
AND NOT EXISTS (Select * from #temphfpefhfref  as b where a.ScrSSN = b.ScrSSN and a.closestdate= b.closestdate)

select distinct scrssn from #temphfreffinal --389,631

select *

into #temphfpeffinal

from #temphfpef as a where a.FirstHF_DischargeDatetime >= '2000-01-01 00:00:00'
AND NOT EXISTS (Select * from #temphfpefhfref  as b where a.ScrSSN = b.ScrSSN and a.closestdate= b.closestdate)

select distinct scrssn from #temphfpeffinal --307,667

select a.*

into #tempexcludedoverlap

from #temphfpefhfref as a where a.FirstHF_DischargeDatetime >= '2000-01-01 00:00:00'
AND NOT EXISTS (Select * from #tempoverlap  as b where a.ScrSSN = b.ScrSSN and a.closestdate= b.closestdate)

select distinct scrssn from #tempexcludedoverlap --68,039

select scrssn, min(closestdate) as secondclosestdate

into #temphfpefhfref1

from #tempexcludedoverlap group by scrssn


