/* Possible HFrEF */

select distinct a.*--, b.DischargeDateTime, c.ICD10ProcedureCode

into Dflt.HeartFailure_poshfref

from Dflt.Heartfailure_HFrEFFinal as a where a.DischargeDateTime > '1990-01-01 00:00:00'
AND NOT EXISTS (Select * from Dflt.HeartFailure_DefHFrEF as b where a.ScrSSN = b.ScrSSN)

select distinct scrssn from Dflt.HeartFailure_poshfref --124,847

