Select distinct b.PatientSID,a.sta3n,b.ScrSSN,b.FirstHF_dischargedatetime,  a.Low_Value, a.high_value, a.valuedatetime, HFrEFType= 'Definitive'

into Dflt.Heartfailure_FinalHFrEF

from Dflt.Heartfailure_HFrEFFinal as a with (NOLOCK) inner join
Dflt.HeartFailure_DefHFrEF as b with (NOLOCK) on a.scrssn= b.ScrSSN 
union all

Select distinct b.PatientSID,a.sta3n,b.ScrSSN,b.FirstHF_dischargedatetime,  a.Low_Value, a.high_value, a.valuedatetime, HFrEFType= 'Possible'
from Dflt.Heartfailure_HFrEFFinal as a with (NOLOCK) inner join
Dflt.HeartFailure_poshfref as b with (NOLOCK) on a.scrssn= b.ScrSSN 

