Select a.scrssn , a.FirstHF_Dischargedatetime,a.age,a.DOB,
b.weightresult,b.heightresult,b.bmi, b.patientsid

into #tempHFpefAgebmi

from Dflt.HeartFailure_HFpEF_Age as a with (NOLOCK) inner join
Dflt.HeartFailure_HFpEFBMI as b with (NOLOCK) on a.scrssn= b.scrssn
where BMI < 100

select distinct scrssn from #tempHFpefAgebmi where bmi > 70 --309,510


select a.*, ((-7.788751 +( 0.062564*a.age) + (0.135149*a.bmi) + 2.040806)) as ABA1 --, (2.71828182845904*ABA1) as abas,(abas/(1+abas)) as ABAFinal

into #temphfpefABA1

from #tempHFpefAgebmi as a with (NOLOCK) inner join
Dflt.HeartFailure_HFpEF_AF as b with (NOLOCK) on a.scrssn= b.scrssn

select distinct scrssn from #temphfpefABA1 --105,237

select *, exp (ABA1) as ABAAF
into #temphfpefABAAF 
from #temphfpefABA1


select *, (ABAAF/(1+ABAAF)) as ABAScore
into #temphfpefABAfinalAF
from #temphfpefABAAF

select distinct * from #temphfpefABAfinalAF --105,237

Select a.*, (-7.788751 +( 0.062564*a.age) + (0.135149*a.bmi)) as ABA2
into #temphfpefABA2
from #tempHFpefAgebmi as a where a.age >=1
AND NOT EXISTS (Select * from Dflt.HeartFailure_HFpEF_AF as b where a.ScrSSN = b.ScrSSN)

select *, exp (ABA2) as ABANOAF
into #temphfpefABANOAF 
from #temphfpefABA2

select distinct scrssn from #temphfpefABA2 --203,996

select *, (ABANOAF/(1+ABANOAF)) as ABAScore
into #temphfpefABAfinalNOAF
from #temphfpefABANOAF

select distinct * from #temphfpefABAfinalNOAF  --204,272

select *
into Dflt.HeartFailure_HFpEF_ABAScore
from #temphfpefABAfinalAF
union all

select *
from #temphfpefABAfinalNOAF

