select distinct scrssn from #tempUCAgebmi --41,923

select top 100* from  Dflt.HeartFailure_UC_AF

select a.*, ((-7.788751 +( 0.062564*a.age) + (0.135149*a.bmi) + 2.040806)) as ABAAF--, (2.71828182845904*ABA1) as abas,(abas/(1+abas)) as ABAFinal

into #tempUCABA1

from #tempUCAgebmi as a with (NOLOCK) inner join
Dflt.HeartFailure_UC_AF as b with (NOLOCK) on a.scrssn= b.scrssn

select *, exp (ABAAF) as ABA1
into #tempUCABAAF
from #tempUCABA1

select distinct scrssn from #tempUCABAAF --10,318

select *, (ABA1/(1+ABA1)) as ABAScore
into #tempUCABAfinalAF
from #tempUCABAAF

select distinct * from #tempUCABAfinalAF --10,318

Select a.*, (-7.788751 +( 0.062564*a.age) + (0.135149*a.bmi)) as ABANOAF
into #tempUCABA2
from #tempUCAgebmi as a where a.age >=1
AND NOT EXISTS (Select * from Dflt.HeartFailure_UC_AF as b where a.ScrSSN = b.ScrSSN)

select distinct scrssn from #tempUCABA2 --31,605

select *, exp (ABANOAF) as ABA2
into #tempUCABANOAF
from #tempUCABA2

select *, (ABA2/(1+ABA2)) as ABAScore
into #tempUCABAfinalNOAF
from #tempUCABANOAF

select distinct * from #tempUCABAfinalNOAF --31,605

select *
into Dflt.HeartFailure_UC_ABAScore
from #tempUCABAfinalAF
union all

select *
from #tempUCABAfinalNOAF

select distinct scrssn from Dflt.HeartFailure_UC_ABAScore --41,923

alter table Dflt.HeartFailure_UC_ABAScore rebuild with (data_compression=page)


/*Combining loop and BNP/PBNP cohort using date filter */

select distinct a.PatientSID, a.ScrSSN, a.FirstHF_dischargedatetime--, a.FillDateTime

into Dflt.HeartFailure_DefUC

from #unclassifiedLoop as a where DaysSupply >=90 
and FillDateTime between dateadd(month, -12,  a.FirstHF_dischargedatetime) and dateadd(month, 6,  a.FirstHF_dischargedatetime)
union all

select a.PatientSID, a.ScrSSN,   a.FirstHF_dischargedatetime--,a.LabChemCompleteDateTime

from #unclassifiedBNPAbove100 as a
where LabChemCompleteDateTime between dateadd(month, -12,  a.FirstHF_dischargedatetime) and dateadd(month, 6,  a.FirstHF_dischargedatetime)
union all 

select a.PatientSID, a.ScrSSN,  a.FirstHF_dischargedatetime --,a.LabChemCompleteDateTime

from #unclassifiedPBNPAbove300 as a
where LabChemCompleteDateTime between dateadd(month, -12,  a.FirstHF_dischargedatetime) and dateadd(month, 6,  a.FirstHF_dischargedatetime)
union all 

select a.patientsid, a.scrssn, a.FirstHF_DischargeDatetime

from Dflt.HeartFailure_UC_ABAScore as a where a.ABAScore >.5

select distinct scrssn from Dflt.HeartFailure_DefUC --38,547

alter table Dflt.HeartFailure_DefUC rebuild with (data_compression=page)

/* Possible Unclassfied */

select distinct a.*--, b.DischargeDateTime, c.ICD10ProcedureCode

into Dflt.HeartFailure_poshUC

from Dflt.HeartFailure_UC as a where a.DischargeDateTime > '1990-01-01 00:00:00'
AND NOT EXISTS (Select * from Dflt.HeartFailure_DefUC as b where a.ScrSSN = b.ScrSSN)

select distinct scrssn from Dflt.HeartFailure_poshUC --17,023

Select distinct b.PatientSID,a.sta3n,b.ScrSSN,a.FirstHF_dischargedatetime, HFUCType= 'Definitive'

into Dflt.Heartfailure_FinalHFUC

from Dflt.HeartFailure_UC as a with (NOLOCK) inner join
Dflt.HeartFailure_DefUC as b with (NOLOCK) on a.scrssn= b.ScrSSN 
union all

Select distinct b.PatientSID,a.sta3n,b.ScrSSN,a.FirstHF_dischargedatetime, HFUCType= 'Possible'
from Dflt.HeartFailure_UC as a with (NOLOCK) inner join
Dflt.HeartFailure_poshUC as b with (NOLOCK) on a.scrssn= b.ScrSSN 

select * from Dflt.Heartfailure_FinalHFUC
select distinct scrssn from Dflt.Heartfailure_FinalHFUC --55,570

alter table Dflt.Heartfailure_FinalHFUC rebuild with (data_compression=page)

/* HFrEF Extraction */
/* Age */

select a.ScrSSN, a.FirstHF_Dischargedatetime, b.DOB,b.SEX
into Dflt.HeartFailure_HFrEF_DOB
from Dflt.HeartFailure_FinalHFrEF as a with (NOLOCK) inner join
Src.VitalStatus_Mini as b with (NOLOCK) on a.scrssn= b.scrssn

select *, datediff( year, DOB, FirstHF_DischargeDatetime) as age
into Dflt.HeartFailure_HFrEF_Age
from Dflt.HeartFailure_HFrEF_DOB

select distinct scrssn from Dflt.HeartFailure_HFrEF_Age--432,533

select distinct scrssn from Dflt.HeartFailure_HFrEF_Age where SEX ='F'--7,714

alter table Dflt.HeartFailure_HFrEF_DOB rebuild with (data_compression=page)

/* Date of Death */

select distinct a.ScrSSN,  b.MPI_DOD
into Dflt.HeartFailure_HFrEF_DOD
from Dflt.HeartFailure_FinalHFrEF as a with (NOLOCK) inner join
Src.SDAF_DAFMaster as b with (NOLOCK) on a.scrssn= b.MPI_scrssn
where b.MPI_DOD is not null

select distinct scrssn from Dflt.HeartFailure_HFrEF_DOD --339,426

alter table Dflt.HeartFailure_HFrEF_DOD rebuild with (data_compression=page)

select *from  Dflt.HeartFailure_HFrEF_DOD 
select top 1000* from Dflt.HeartFailure_FinalHFrEF

/* Race */

select a.*,  b.Race
into Dflt.HeartFailure_HFrEF_Race
from Dflt.HeartFailure_FinalHFrEF as a with (NOLOCK) inner join
Src.PatSub_PatientRace as b with (NOLOCK) on a.patientsid= b.patientsid

select distinct scrssn from  Dflt.HeartFailure_HFrEF_Race --394,869

alter table Dflt.HeartFailure_HFrEF_Race rebuild with (data_compression=page)

