alter table Dflt.HeartFailure_HFrEF_Diabetes rebuild with (data_compression=page)

/* Select height and weight values from vital signs view to calculate bmi */

select distinct a.PatientSID, a.VitalSignTakenDateTime, a.VitalResult, a.VitalResultNumeric,
b.FirstHF_Dischargedatetime,b.ScrSSN,
c.VitalType

into #temphfrefVitals

from Src.Vital_VitalSign as a with (NOLOCK) inner join
Dflt.HeartFailure_FinalHFrEF as b with (NOLOCK) on a.PatientSID= b.PatientSID inner join 
CDWWork.Dim.VitalType as c with (NOLOCK) on a.VitalTypeSID=c.VitalTypeSID 
where (a.VitalSignTakenDateTime between dateadd(month, -12, b.FirstHF_Dischargedatetime) and dateadd(DAY, 1, b.FirstHF_Dischargedatetime)) AND
c.VitalType in ( 'WEIGHT')
union all

select distinct a.PatientSID, a.VitalSignTakenDateTime, a.VitalResult, a.VitalResultNumeric,
b.FirstHF_Dischargedatetime,b.ScrSSN, 
c.VitalType

from Src.Vital_VitalSign_Recent as a with (NOLOCK) inner join
Dflt.HeartFailure_FinalHFrEF as b with (NOLOCK) on a.PatientSID= b.PatientSID inner join 
CDWWork.Dim.VitalType as c with (NOLOCK) on a.VitalTypeSID=c.VitalTypeSID 
where (a.VitalSignTakenDateTime between dateadd(month, -12, b.FirstHF_Dischargedatetime) and dateadd(day, 1, b.FirstHF_Dischargedatetime)) AND 
c.VitalType in ( 'WEIGHT')
union all

select distinct a.PatientSID, a.VitalSignTakenDateTime, a.VitalResult, a.VitalResultNumeric,
b.FirstHF_Dischargedatetime, b.ScrSSN, 
c.VitalType

from Src.Vital_VitalSign as a with (NOLOCK) inner join
Dflt.HeartFailure_FinalHFrEF as b with (NOLOCK) on a.PatientSID= b.PatientSID inner join 
CDWWork.Dim.VitalType as c with (NOLOCK) on a.VitalTypeSID=c.VitalTypeSID 
