select distinct scrssn from #temphfrefVitals --418,518

/* Seperate weight records into a table */
select * 

into #tempweighthfref

from #temphfrefVitals where vitaltype = 'WEIGHT' and VitalResultNumeric != '0'

select distinct scrssn from #tempweighthfref --408,119

select scrssn, max (VitalSignTakenDateTime) as VitalSignTakenDateTime
into #tempweight1hfref
from #tempweighthfref group by scrssn

select distinct a.patientsid, b.scrssn, b.VitalSignTakenDateTime, a.VitalResult, a.VitalResultNumeric
into #tempweightfinalhfref
from #tempweighthfref as a with (NOLOCK) left outer join 
#tempweight1hfref as b with (NOLOCK) on a.scrssn= b.scrssn and a.VitalSignTakenDateTime= b.VitalSignTakenDateTime

select distinct scrssn from #tempweightfinalhfref --408,120

/* Seperate height records into a table */
select *  

into #tempheighthfref

from #temphfrefVitals where vitaltype = 'HEIGHT' and VitalResultNumeric != '0'

select distinct scrssn from #tempheighthfref--393,539

select scrssn, max (VitalSignTakenDateTime) as VitalSignTakenDateTime
into #tempheight1hfref
from #tempheighthfref group by scrssn

select distinct a.patientsid, b.scrssn, b.VitalSignTakenDateTime, a.VitalResult, a.VitalResultNumeric
into #tempheightfinalhfref
from #tempheighthfref as a with (NOLOCK) left outer join 
#tempheight1hfref as b with (NOLOCK) on a.scrssn= b.scrssn and a.VitalSignTakenDateTime= b.VitalSignTakenDateTime

select distinct scrssn from #tempheightfinalhfref --393,540

/* Combine data from table weight and height to obtain the bmi for individual patient */

select distinct a.patientsid, a.ScrSSN, cast(a.VitalSignTakenDateTime as date) as HeightTime, a.VitalResultNumeric as heightresult, 
cast(b.VitalSignTakenDateTime as date) as WeightTime,b.VitalResultNumeric as weightresult, ((b.VitalResultNumeric*703)/(a.VitalResultNumeric*a.VitalResultNumeric)) as bmi

into Dflt.HeartFailure_HFrEF_BMI

from #tempheightfinalhfref as a with (NOLOCK) inner join
#tempweightfinalhfref as b with (NOLOCK) on a.ScrSSN = b.ScrSSN

select distinct scrssn from Dflt.HeartFailure_HFrEF_BMI --383,173

alter table Dflt.HeartFailure_HFrEF_BMI rebuild with (data_compression=page)

