select distinct ICD10Code from CDWWork.Dim.ICD10 where ICD10Code in ('I63.019','I63.119','I63.139','I63.20','I63.219','I63.22','I63.239','I63.30','I63.40','I63.50','I63.59')
select distinct ICD10Code from CDWWork.Dim.ICD10 where ICD10Code like 'I6[0-3].%'
select distinct ICD9Code from CDWWork.Dim.ICD9 where ICD9Code in ('433.21','433.11','433.91','433.01','434.01','434.11','434.91','433.31','433.81')
select distinct ICD9Code from CDWWork.Dim.ICD9 where ICD9Code like '43[3-4,6].%'

select distinct a.patientsid, a.scrssn, a.FirstHF_DischargeDatetime, b.DischargeDateTime as comorbidity_Dischargedatettime, c.ICD9Code as comorbidity_ICD9Code
/*ICD9 Codes*/

into Dflt.HeartFailure_HFpEF_Stroke

from Dflt.HeartFailure_FinalHFpEF as a with (NOLOCK) inner join
Src.Inpat_InpatientDiagnosis as b with (NOLOCK) on a.PatientSID= b.PatientSID inner join 
CDWWork.Dim.ICD9 as c with (NOLOCK) on b.ICD9SID=c.ICD9SID 
where c.ICD9Code like '43[3-4,6].%' 
					and b.DischargeDateTime <= a.FirstHF_DischargeDatetime
union all

select distinct a.patientsid, a.scrssn, a.FirstHF_DischargeDatetime, b.DischargeDateTime, c.ICD9Code

from Dflt.HeartFailure_FinalHFpEF as a with (NOLOCK) inner join
Src.Inpat_InpatientDiagnosis_Recent as b with (NOLOCK) on a.PatientSID= b.PatientSID inner join 
CDWWork.Dim.ICD9 as c with (NOLOCK) on b.ICD9SID=c.ICD9SID 
where c.ICD9Code like '43[3-4,6].%' 
					and b.DischargeDateTime <= a.FirstHF_DischargeDatetime
union all

select distinct a.patientsid, a.scrssn, a.FirstHF_DischargeDatetime, b.DischargeDateTime, c.ICD9Code

from Dflt.HeartFailure_FinalHFpEF as a with (NOLOCK) inner join
Src.Inpat_InpatientFeeDiagnosis as b with (NOLOCK) on a.PatientSID= b.PatientSID inner join 
CDWWork.Dim.ICD9 as c with (NOLOCK) on b.ICD9SID=c.ICD9SID 
