alter table Dflt.HeartFailure_HFpEF_Diabetes rebuild with (data_compression=page)

/* Select height and weight values from vital signs view to calculate bmi */

select distinct a.PatientSID, a.VitalSignTakenDateTime, a.VitalResult, a.VitalResultNumeric,
b.FirstHF_Dischargedatetime,b.ScrSSN,
c.VitalType

into #tempHFpEFVitals

from Src.Vital_VitalSign as a with (NOLOCK) inner join
Dflt.HeartFailure_FinalHFpEF as b with (NOLOCK) on a.PatientSID= b.PatientSID inner join 
CDWWork.Dim.VitalType as c with (NOLOCK) on a.VitalTypeSID=c.VitalTypeSID 
where (a.VitalSignTakenDateTime between dateadd(month, -12, b.FirstHF_Dischargedatetime) and dateadd(DAY, 1, b.FirstHF_Dischargedatetime)) AND
c.VitalType in ( 'WEIGHT')
union all

select distinct a.PatientSID, a.VitalSignTakenDateTime, a.VitalResult, a.VitalResultNumeric,
b.FirstHF_Dischargedatetime,b.ScrSSN, 
c.VitalType

from Src.Vital_VitalSign_Recent as a with (NOLOCK) inner join
Dflt.HeartFailure_FinalHFpEF as b with (NOLOCK) on a.PatientSID= b.PatientSID inner join 
CDWWork.Dim.VitalType as c with (NOLOCK) on a.VitalTypeSID=c.VitalTypeSID 
where (a.VitalSignTakenDateTime between dateadd(month, -12, b.FirstHF_Dischargedatetime) and dateadd(day, 1, b.FirstHF_Dischargedatetime)) AND 
c.VitalType in ( 'WEIGHT')
union all

select distinct a.PatientSID, a.VitalSignTakenDateTime, a.VitalResult, a.VitalResultNumeric,
b.FirstHF_Dischargedatetime, b.ScrSSN, 
c.VitalType

from Src.Vital_VitalSign as a with (NOLOCK) inner join
Dflt.HeartFailure_FinalHFpEF as b with (NOLOCK) on a.PatientSID= b.PatientSID inner join 
CDWWork.Dim.VitalType as c with (NOLOCK) on a.VitalTypeSID=c.VitalTypeSID 
--where (a.VitalSignTakenDateTime between dateadd(month, -12, b.SGLT2FillTime) and dateadd(day, 1, b.SGLT2FillTime))AND
where a.VitalSignTakenDateTime <= b.FirstHF_Dischargedatetime and 
c.VitalType in ( 'HEIGHT')
union all

select distinct a.PatientSID, a.VitalSignTakenDateTime, a.VitalResult, a.VitalResultNumeric,
b.FirstHF_Dischargedatetime,b.ScrSSN, 
c.VitalType

from Src.Vital_VitalSign_Recent as a with (NOLOCK) inner join
Dflt.HeartFailure_FinalHFpEF as b with (NOLOCK) on a.PatientSID= b.PatientSID inner join 
CDWWork.Dim.VitalType as c with (NOLOCK) on a.VitalTypeSID=c.VitalTypeSID 
--where (a.VitalSignTakenDateTime between dateadd(month, -12, b.SGLT2FillTime) and dateadd(day, 1, b.SGLT2FillTime))AND
where a.VitalSignTakenDateTime <= b.FirstHF_Dischargedatetime and 
c.VitalType in ( 'HEIGHT')

select distinct scrssn from #tempHFpEFVitals --327,357

/* Seperate weight records into a table */
select * 

into #tempweightHFpEF

from #tempHFpEFVitals where vitaltype = 'WEIGHT' and VitalResultNumeric != '0'

select distinct scrssn from #tempweightHFpEF --320,669

select scrssn, max (VitalSignTakenDateTime) as VitalSignTakenDateTime
into #tempweight1HFpEF
from #tempweightHFpEF group by scrssn

select distinct a.patientsid, b.scrssn, b.VitalSignTakenDateTime, a.VitalResult, a.VitalResultNumeric
into #tempweightfinalHFpEF
from #tempweightHFpEF as a with (NOLOCK) left outer join 
#tempweight1HFpEF as b with (NOLOCK) on a.scrssn= b.scrssn and a.VitalSignTakenDateTime= b.VitalSignTakenDateTime

select distinct scrssn from #tempweightfinalHFpEF --320,670

/* Seperate height records into a table */
select *  

into #tempheightHFpEF

from #tempHFpEFVitals where vitaltype = 'HEIGHT' and VitalResultNumeric != '0'

select distinct scrssn from #tempheightHFpEF--316,189

select scrssn, max (VitalSignTakenDateTime) as VitalSignTakenDateTime
into #tempheight1HFpEF
from #tempheightHFpEF group by scrssn

select distinct a.patientsid, b.scrssn, b.VitalSignTakenDateTime, a.VitalResult, a.VitalResultNumeric
into #tempheightfinalHFpEF
from #tempheightHFpEF as a with (NOLOCK) left outer join 
#tempheight1HFpEF as b with (NOLOCK) on a.scrssn= b.scrssn and a.VitalSignTakenDateTime= b.VitalSignTakenDateTime

select distinct scrssn from #tempheightfinalHFpEF --316,190

/* Combine data from table weight and height to obtain the bmi for individual patient */

select distinct a.patientsid, a.ScrSSN, cast(a.VitalSignTakenDateTime as date) as HeightTime, a.VitalResultNumeric as heightresult, 
cast(b.VitalSignTakenDateTime as date) as WeightTime,b.VitalResultNumeric as weightresult, ((b.VitalResultNumeric*703)/(a.VitalResultNumeric*a.VitalResultNumeric)) as bmi

into Dflt.HeartFailure_HFpEF_BMI

from #tempheightfinalHFpEF as a with (NOLOCK) inner join
#tempweightfinalHFpEF as b with (NOLOCK) on a.ScrSSN = b.ScrSSN

select distinct scrssn from Dflt.HeartFailure_HFpEF_BMI --309,526

alter table Dflt.HeartFailure_HFpEF_BMI rebuild with (data_compression=page)

