select distinct a.scrssn, a.patientsid, b.DischargeDateTime, c.ICD10Code

from Dflt.HeartFailure_FinalHFpEF as a with (NOLOCK) inner join
Src.Inpat_InpatientFeeDiagnosis as b with (NOLOCK) on a.PatientSID= b.PatientSID inner join 
CDWWork.Dim.ICD10 as c with (NOLOCK) on b.ICD10SID=c.ICD10SID 
where b.DischargeDateTime >= dateadd(day,7,a.FirstHF_dischargedatetime)
union all

select distinct a.scrssn, a.patientsid, b.PatientTransferDateTime, c.ICD10Code

from Dflt.HeartFailure_FinalHFpEF as a with (NOLOCK) inner join
Src.Inpat_PatientTransferDiagnosis as b with (NOLOCK) on a.PatientSID= b.PatientSID inner join 
CDWWork.Dim.ICD10 as c with (NOLOCK) on b.ICD10SID=c.ICD10SID 
where b.PatientTransferDateTime >= dateadd(day,7,a.FirstHF_dischargedatetime)

union all

select distinct a.scrssn, a.patientsid, b.SpecialtyTransferDateTime, c.ICD10Code

from Dflt.HeartFailure_FinalHFpEF as a with (NOLOCK) inner join
Src.Inpat_SpecialtyTransferDiagnosis as b with (NOLOCK) on a.PatientSID= b.PatientSID inner join 
CDWWork.Dim.ICD10 as c with (NOLOCK) on b.ICD10SID=c.ICD10SID 
where b.SpecialtyTransferDateTime >= dateadd(day,7,a.FirstHF_dischargedatetime)
union all

select distinct a.scrssn, a.patientsid, b.AdmitDateTime, c.ICD10Code

from Dflt.HeartFailure_FinalHFpEF as a with (NOLOCK) inner join
Src.Inpat_InpatDischargeDiagnosis as b with (NOLOCK) on a.PatientSID= b.PatientSID inner join 
CDWWork.Dim.ICD10 as c with (NOLOCK) on b.ICD10SID=c.ICD10SID 
where  b.AdmitDateTime >= dateadd(day,7,a.FirstHF_dischargedatetime)

select distinct scrssn from Dflt.HFpEF_AllHospitalization --276,579
alter table Dflt.HFpEF_AllHospitalization  rebuild with (data_compression=page)

/* HFUC Extraction */
/* Age */

select a.ScrSSN, a.FirstHF_Dischargedatetime, b.DOB,b.SEX
into Dflt.HeartFailure_HFUC_DOB
from Dflt.HeartFailure_FinalHFUC as a with (NOLOCK) inner join
Src.VitalStatus_Mini as b with (NOLOCK) on a.scrssn= b.scrssn

select *, datediff( year, DOB, FirstHF_DischargeDatetime) as age
into Dflt.HeartFailure_HFUC_Age
from Dflt.HeartFailure_HFUC_DOB

select distinct scrssn from Dflt.HeartFailure_HFUC_Age--55,483

select distinct scrssn from Dflt.HeartFailure_HFUC_Age where SEX ='F'--1,626

alter table Dflt.HeartFailure_HFUC_DOB rebuild with (data_compression=page)

/* Date of Death */

select distinct a.ScrSSN,  b.MPI_DOD
into Dflt.HeartFailure_HFUC_DOD
from Dflt.HeartFailure_FinalHFUC as a with (NOLOCK) inner join
Src.SDAF_DAFMaster as b with (NOLOCK) on a.scrssn= b.MPI_scrssn
where b.MPI_DOD is not null

select distinct scrssn from Dflt.HeartFailure_HFUC_DOD --49,465

alter table Dflt.HeartFailure_HFUC_DOD rebuild with (data_compression=page)

/* Race */

select a.*,  b.Race
into Dflt.HeartFailure_HFUC_Race
from Dflt.HeartFailure_FinalHFUC as a with (NOLOCK) inner join
Src.PatSub_PatientRace as b with (NOLOCK) on a.patientsid= b.patientsid

select distinct scrssn from  Dflt.HeartFailure_HFUC_Race --41,488

alter table Dflt.HeartFailure_HFUC_Race rebuild with (data_compression=page)

/* Comorbidities */
/* Hypertension */

select distinct a.*, b.DischargeDateTime as comorbidity_Dischargedatetime, c.ICD9Code as comorbidity_ICD9Code
/*ICD9 Codes*/

into Dflt.HeartFailure_HFUC_Hypertension

from Dflt.HeartFailure_FinalHFUC as a with (NOLOCK) inner join
Src.Inpat_InpatientDiagnosis as b with (NOLOCK) on a.PatientSID= b.PatientSID inner join 
CDWWork.Dim.ICD9 as c with (NOLOCK) on b.ICD9SID=c.ICD9SID 
where c.ICD9Code in ('401.1','401.0','401.9','402.00','402.01','402.90','402.91','403.00','403.01','403.10','403.11','403.90','403.91','404.00','404.01','404.02','404.03','404.10',
					'404.11','404.12','404.13','404.90','404.91','404.92','404.93','405.01','405.09','405.11','405.99','642.00','642.01','642.02','642.03','642.04','642.10','642.11',
					'642.12','642.13','642.14','642.20','642.21','642.22','642.23','642.24','642.70','642.71','642.72','642.73','642.74','642.90','642.91','642.92','642.93','642.94')
					and b.DischargeDateTime between dateadd(month, -12, a.FirstHF_DischargeDatetime) and dateadd(day, 1, a.FirstHF_DischargeDatetime)
union all

