/* Atrial Fibrillation After first incident HF- using only principal diagnosis table */
/*HFpEF*/

select distinct a.PatientSID,a.ScrSSN, a.FirstHF_DischargeDatetime, b.DischargeDateTime as comorbidity_Dischargedatetime, c.ICD9Code as comorbidity_ICD9Code, b.AdmitDiagnosis
/*ICD9 Codes*/

into Dflt.HFpEF_AFAfter

from Dflt.HeartFailure_FinalHFpEF as a with (NOLOCK) inner join
Src.Inpat_Inpatient as b with (NOLOCK) on a.PatientSID= b.PatientSID inner join 
CDWWork.Dim.ICD9 as c with (NOLOCK) on b.PrincipalDiagnosisICD9SID=c.ICD9SID 
where c.ICD9Code in ('427.31')
					and b.DischargeDateTime >= a.FirstHF_DischargeDatetime
union all


/*ICD10 Codes*/
select distinct a.PatientSID,a.ScrSSN, a.FirstHF_DischargeDatetime, b.DischargeDateTime, c.ICD10Code, b.AdmitDiagnosis

from Dflt.HeartFailure_FinalHFpEF as a with (NOLOCK) inner join
Src.Inpat_Inpatient as b with (NOLOCK) on a.PatientSID= b.PatientSID inner join 
CDWWork.Dim.ICD10 as c with (NOLOCK) on b.PrincipalDiagnosisICD10SID=c.ICD10SID 
where ICD10Code like 'I48.%'
and b.DischargeDateTime >= a.FirstHF_DischargeDatetime
 
