Src.Outpat_VDiagnosis as b with (NOLOCK) on a.PatientSID= b.PatientSID inner join 
CDWWork.Dim.ICD9 as c with (NOLOCK) on b.ICD9SID=c.ICD9SID 
where c.ICD9Code in ('427.31')
					and b.EventDateTime >= a.FirstHF_Dischargedatetime
union all

select distinct a.PatientSID,a.ScrSSN,  a.FirstHF_Dischargedatetime, b.EventDateTime, c.ICD9Code

from Dflt.HeartFailure_FinalHFUC as a with (NOLOCK) inner join
